// Single place that defines where benchmark data lives.
// The workflow copies the bench-results branch's data/ folder to site/data/.
// Expected layout on bench-results (assumption until the harness README defines it):
//   data/latest.json        newest registered run (schema: see site/README-data in app.js header)
//   data/runs/*.json        one file per registered run, same schema
// data/index.json = {"runs":[<full run objects, oldest first>]}, generated by the Pages workflow from data/runs/*.json.
window.BENCH_CONFIG = {
  DATA_DIR: "data/",
  LATEST: "data/latest.json",
  INDEX: "data/index.json",
  PREREG_VERSIONS: ["v1", "v2"],      // versions this page knows
  PREREG_CURRENT: "v2",               // the version the Method section presents
  MIN_TREATMENT_RATE: 0.8,            // prereg v2: a run is VALID only if >= 80 % of cc sessions received the treatment
  // Runs whose treatment failure is documented in the prereg v2 change log but not recorded in the run row.
  KNOWN_TREATMENT_FAILURES: { "20261009-101417": "0 of 12 cc sessions called code-context, per the prereg v2 change log" },
  REPO: "https://github.com/VelimirMueller/code-context-mcp"
};
